const ThemeContext = createContext(null);
const SearchContext = createContext(null);

function HeavyPanel() {
  const theme = useContext(ThemeContext); // only subscribes to theme
  let work = 0;
  for (let i = 0; i < 2000000; i++) work += i;
  return <div style={{ padding: 8 }}>Panel ({theme}) – render cost {work > 0 ? 'high' : ''}</div>;
}

function SearchBox() {
  const { query, setQuery } = useContext(SearchContext);
  return <input value={query} onChange={e => setQuery(e.target.value)} placeholder="search" />;
}

function App() {
  const [theme] = useState('light');
  const [query, setQuery] = useState('');
  const search = useMemo(() => ({ query, setQuery }), [query]);
  return (
    <ThemeContext.Provider value={theme}>
      <SearchContext.Provider value={search}>
        <div style={{ fontFamily: 'system-ui', padding: 16 }}>
          <SearchBox />
          <HeavyPanel />
        </div>
      </SearchContext.Provider>
    </ThemeContext.Provider>
  );
}

const AuthContext = createContext(null);

function Layout() {
  return <UserBadge />; // passes nothing
}

function UserBadge() {
  const { user, login, logout } = useContext(AuthContext);
  return (
    <div style={{ fontFamily: 'system-ui' }}>
      {user
        ? <><span>Hi, {user}</span> <button onClick={logout}>Logout</button></>
        : <button onClick={() => login('Nihal')}>Login</button>}
    </div>
  );
}

function App() {
  const [user, setUser] = useState(null);
  const value = useMemo(() => ({
    user,
    login: (name) => setUser(name),
    logout: () => setUser(null)
  }), [user]);
  return (
    <AuthContext.Provider value={value}>
      <div style={{ padding: 16 }}><Layout /></div>
    </AuthContext.Provider>
  );
}
